"note": "Named as the surety on Asher and Sarah's 1856 marriage bond — in Kentucky practice almost always the bride's father or close kin. Recorded as Sarah's likely father (inferred from the bond, flagged). Relatives of the same family appear throughout Breckinridge County records: Daniel F. Lampton's 1850 household, Alpheus M. Lampton's 1856 marriage.",
