"lines": [
{
"t": "Pullen",
"d": "The direct line: Asher B. Pullen (b. 1834, Breckinridge Co., Kentucky) → Texas → Ohio and Kentucky → Jacob today. The 1850 census shows the children in District 2, Breckinridge County; the 1820 census lists Pullens Richard, George, Abraham and Isaiah on a single page.",
"from": "Kentucky, 1820 census (earliest trace)",
"flag": ""
},
{
"t": "Lampton",
"d": "Sarah J. Lampton (1836–1921) — her marriage-bond surety was Arslem W. Lampton, likely her father. The Lampton family of Breckinridge County appears in the 1820 census: Edward, Thomas C., Henry and Joshua Lampton.",
"from": "Kentucky, 1820 census",
"flag": ""
},
{
"t": "Hart",
"d": "Ada Hart ← Uriah Hart (1824–1896) + Harriett Wooldridge ← Abraham Hart (1797–1847) + Amelia Terry (1800–1887).",
"from": "Kentucky, 1820s (census-checked)",
"flag": ""
},
{
"t": "Wooldridge",
"d": "Harriett Wooldridge (1828–1913) of Grayson County — her parents are the next rung up.",
"from": "open — next rung unknown",
"flag": ""
},
{
"t": "West",
"d": "Eva Lee West Pullen (1897-1977), wife of Rannie Pullen — born at Caddo Gap, Arkansas, died at Childress, Texas; daughter of Robert Bonapart West + Mary Elizabeth Weatherred West.",
"from": "open — next rung unknown",
"flag": ""
},
{
"t": "Fry",
"d": "Rose Marie “R” Fry (b. 1927, Kenton Co.) ← mother Marie Burns (Kentucky birth index); brother Bernard W. Fry (b. 1941, Kenton Co.). The Burns line is the next rung.",
"from": "Kentucky — next rung: Burns",
"flag": ""
},
{
"t": "Jordan",
"d": "Charlene Jordan ← Harle Jordan + Eulah Mae Elliott ← Tip Jordan (1904–1993) + Malvie Smith ← James H. Jordan + Cordelia Gibbons ← William O. Jordan + Eunice Bargo ← John J. B. Bargo Sr. + Elizabeth Baker, with Abigail Payne above.",
"from": "Kentucky / Virginia, 1820s",
"flag": ""
},
{
"t": "Bargo",
"d": "John J. B. Bargo Sr. (1823–1900) + Elizabeth Baker (1822–1910).",
"from": "open — next rung unknown",
"flag": ""
},
{
"t": "Elliott",
"d": "Eulah Mae Elliott ← Perry Elliott ← David D. Elliott + Elizabeth Taylor ← Hugh Elliott + Lydia Engle.",
"from": "open — next rung unknown",
"flag": ""
},
{
"t": "Bryant / Parker / Grant",
"d": "Mattie Bryant ← Isaac L. Bryant + Parmelia Parker ← Wallace Parker + Rebecca J. Washam; George Grant + Lydie Fennall above (parent links flagged for verification).",
"from": "open — next rung unknown",
"flag": "⚠️"
},
{
"t": "Schooler",
"d": "Alexa Schooler ← Orvell W. Schooler + Charlene Jordan ← Prentice A. Schooler + Inez M. Hamilton.",
"from": "Kentucky, 1900s",
"flag": ""
},
{
"t": "Hamilton / Coleman / Holliday",
"d": "Inez M. Hamilton ← Artie Coleman + Lillian Stewart ← James S. Coleman + Louisa V. Holliday ← Samuel L. Holliday + Mary E. McDonald.",
"from": "open — next rung unknown",
"flag": ""
},
{
"t": "Collins",
"d": "Carlene Collins ← Lucian Collins (1918-1998, b. Boyle Co.; the family tree's 1896 corrected by the birth index) + Genova Hammons (“Gineva M. Hammons” in the index, b. June 29, 1935, Boyle Co., mother Sadie Preston). Carlene married Robert M. Pullen (1973) and Shirley T. Harmon (1979). Lucian's parents were Walter “Jack” Collins and Mary Burger, and his brothers-and-sisters: Walter (1903), James (1907), Fred (1911), Nellie (1915), Robert (1921, died an infant) and Sherman. Lucian's earlier children by Grace Belden: Lucien Jr. (1939) and Joe A. (1941). Her Boyle County siblings: Judy C. Hogue (1950), Rickey A. Cunningham (1953), Lucien M. Collins (1957), James Eric Poynter (1967), Timothy Dewayne Goodlett (1969).",
"from": "Kentucky, 1800s",
"flag": ""
},
{
"t": "Hammons / Whitten",
"d": "Genova Hammons ← Carl Rose Hammons + Sadie E. Preston (children: Gertrude 1926, Arthur G. 1930, Geneva 1935, Geraldine 1946 — all Boyle Co.; death index: Carl R. Hammons, d. Nov 16, 1947, Boyle Co.) ← John F. Hammons + Cecilia G. Whitten ← Squire G. Whitten ← James J. Whitten ← George H. Whitten ← John W. Whitten (1740–1810) + Elizabeth Hinson.",
"from": "Virginia, 1740",
"flag": ""
},
{
"t": "Owens / Cox / Preston",
"d": "Maggie J. Owens ← Joshua P. Owens + Sarah J. Christison ← Jeremiah Owens + Frances Cox ← Samuel Cox + Ellen Brown; John C. Preston + Maggie J. Owens above Sadie.",
"from": "open — next rung unknown",
"flag": ""
}
]
